export function verifyToken(token, now = Date.now()) {
  if (!token || typeof token !== 'object') return { valid: false, reason: 'missing' };
  // BUG: does not check token.exp
  return { valid: true, user: token.user, role: token.role || 'viewer' };
}

files.src/middleware.js:
import { verifyToken } from './auth.js';

export function authorize(token, requiredRole, now = Date.now()) {
  const res = verifyToken(token, now);
  if (!res.valid) return { allowed: false, status: 401, reason: res.reason };
  // BUG: strict case comparison fails when token role is 'ADMIN' vs 'admin'
  if (requiredRole && res.role !== requiredRole) {
    return { allowed: false, status: 403, reason: 'forbidden' };
  }
  return { allowed: true, status: 200, user: res.user };
}

