export function parseSemver(v) {
  const [core] = String(v).replace(/^v/, '').split('-');
  const [major, minor, patch] = core.split('.').map(Number);
  // BUG: drops prerelease identifiers
  return { major, minor, patch, prerelease: [] };
}

